import SwiftUI

struct ExpenseCard: View {
    let expense: Expense
    var isExpanded = false

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(expense.title)
                .font(.headline)
            if isExpanded {
                Text(expense.date, format: .dateTime.weekday().day().month())
                Text(expense.category.title)
            }
            Button(isExpanded ? "Less" : "More") {
                isExpanded.toggle()
            }
        }
    }
}
